    </div>`);
}

async function readForm(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 64 * 1024) return null;
  }
  return new URLSearchParams(body);
}

function redirect(response, location) {
  response.writeHead(303, { Location: location });
  response.end();
}

const server = http.createServer(async (request, response) => {
  try {
    const url = new URL(request.url, 'http://localhost');
    if (request.method === 'GET' && url.pathname === '/health') {
      response.writeHead(200, { 'Content-Type': 'application/json' });
      response.end(JSON.stringify({ status: 'ok' }));
      return;
    }
    if (request.method === 'GET' && url.pathname === '/') {
      sendHtml(response, 200, projectsPage('', projectFilter(url.searchParams.get('filter'))));
      return;
    }
    if (request.method === 'POST' && url.pathname === '/projects') {
      const form = await readForm(request);
      if (!form) {
        sendHtml(response, 413, page('Request too large', '<h1>Request too large</h1>'));
        return;
      }
      const name = (form.get('name') || '').trim();
      if (!name) {
        sendHtml(response, 422, projectsPage('Project name is required', projectFilter(form.get('filter'))));
        return;
      }
      createProject.run(name);
      redirect(response, '/');
      return;
    }
    const archiveMatch = /^\/projects\/([1-9]\d*)\/(archive|restore)$/.exec(url.pathname);
    if (archiveMatch && request.method === 'POST') {
      const id = Number(archiveMatch[1]);
      if (Number.isSafeInteger(id) && findProject.get(id)) {
        setProjectArchived.run(archiveMatch[2] === 'archive' ? 1 : 0, id);
        redirect(response, archiveMatch[2] === 'restore' ? '/?filter=Archived' : '/');
        return;
      }
    }
    const projectMatch = /^\/projects\/([1-9]\d*)(?:\/(?:(tasks)(?:\/([1-9]\d*)\/(?:completion|rename|priority))?|(rename|default-priority)))?$/.exec(url.pathname);
    if (projectMatch) {
      const id = Number(projectMatch[1]);
      const project = Number.isSafeInteger(id) ? findProject.get(id) : undefined;
      if (project && request.method === 'GET' && !projectMatch[2] && !projectMatch[4]) {
        sendHtml(response, 200, projectPage(project, taskFilter(url.searchParams.get('filter')), '', '', null, priorityFilter(url.searchParams.get('priorityFilter'))));
        return;
      }
      if (project && request.method === 'POST' && (projectMatch[2] || projectMatch[4])) {
        const form = await readForm(request);
        if (!form) {
          sendHtml(response, 413, page('Request too large', '<h1>Request too large</h1>'));
          return;
        }
        const filter = taskFilter(form.get('filter'));
        const selectedPriority = priorityFilter(form.get('priorityFilter'));
        const currentProject = findProject.get(id);
        if (currentProject.archived) {
          sendHtml(response, 403, projectPage(currentProject, filter, 'Archived project cannot be changed', '', null, selectedPriority));
          return;
        }
        if (projectMatch[4] === 'default-priority') {
          const priority = form.get('priority');
          if (!['Low', 'Normal', 'High'].includes(priority)) {
            sendHtml(response, 422, page('Invalid priority', '<p role="alert">Invalid task priority</p>'));
            return;
          }
          setDefaultTaskPriority.run(priority, id);
        } else if (projectMatch[4] === 'rename') {
          const name = (form.get('name') || '').trim();
          if (!name) {
            sendHtml(response, 422, projectPage(currentProject, filter, '', 'Project name is required', null, selectedPriority));
            return;
          }
          renameProject.run(name, id);
        } else if (projectMatch[3]) {
          const taskId = Number(projectMatch[3]);
          if (!Number.isSafeInteger(taskId) || !findTask.get(taskId, project.id)) {
            sendHtml(response, 404, page('Not found', '<h1>Task not found</h1>'));
            return;
          }
          if (url.pathname.endsWith('/rename')) {
            const title = (form.get('title') || '').trim();
            if (!title) {
              sendHtml(response, 422, projectPage(currentProject, filter, '', '', { id: taskId }, selectedPriority));
              return;
            }
            renameTask.run(title, taskId, project.id);
          } else if (url.pathname.endsWith('/priority')) {
            const priority = form.get('priority');
            if (!['Low', 'Normal', 'High'].includes(priority)) {
              sendHtml(response, 422, page('Invalid priority', '<p role="alert">Invalid task priority</p>'));
              return;
            }
            setTaskPriority.run(priority, taskId, project.id);
          } else {
            updateTask.run(form.get('completed') === '1' ? 1 : 0, taskId, project.id);
          }
        } else {
          const title = (form.get('title') || '').trim();
          if (!title) {
            sendHtml(response, 422, projectPage(project, filter, 'Task title is required', '', null, selectedPriority));
            return;
          }
          createTask.run(project.id, title, currentProject.default_task_priority);
        }
        redirect(response, projectLocation(project.id, filter, selectedPriority));
        return;
      }
    }
    sendHtml(response, 404, page('Not found', '<h1>Page not found</h1><form action="/"><button>Projects</button></form>'));
  } catch (error) {
    console.error(error);
    if (!response.headersSent) {
      sendHtml(response, 500, page('Server error', '<h1>Something went wrong</h1>'));
    } else {
      response.end();
    }
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

function shutdown() {
  server.close(() => {
    database.close();
  });
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

